const FILES = 'abcdefgh'
const PIECE_NAMES = { p: 'P', n: 'N', b: 'B', r: 'R', q: 'Q', k: 'K' }
const START_FEN = 'rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w'
const SAMPLE_PUZZLE = {
  game: { id: 'sample', fen: '6k1/5ppp/8/8/8/8/5PPP/6K1 w' },
  puzzle: {
    id: 'sample-mate-net',
    rating: 1200,
    solution: ['g2g4'],
    themes: ['quietMove', 'endgame', 'advantage'],
    source: 'sample'
  },
  notice: 'Offline sample position shown while the Lichess daily puzzle is unavailable.'
}

function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value))
}

function boolValue(value, fallback) {
  if (value === undefined || value === null || value === '') return fallback
  return value === true || value === 'true'
}

function hex(value, fallback) {
  const text = String(value || '').trim()
  return /^#[0-9a-fA-F]{6}$/.test(text) ? text : fallback
}

function moveToText(move) {
  if (!move || move.length < 4) return ''
  const promo = move.length > 4 ? '=' + move.charAt(4).toUpperCase() : ''
  // An en dash between the squares: the frame's fonts have no arrow.
  return move.substring(0, 2) + '–' + move.substring(2, 4) + promo
}

function titleCaseTheme(theme) {
  return String(theme || '')
    .replace(/([a-z])([A-Z])/g, '$1 $2')
    .replace(/_/g, ' ')
    .toLowerCase()
    .replace(/\b\w/g, function (m) { return m.toUpperCase() })
}

function cloneBoard(board) {
  return board.map(function (row) { return row.slice() })
}

function initialBoard() {
  return [
    'rnbqkbnr'.split(''),
    'pppppppp'.split(''),
    '        '.split(''),
    '        '.split(''),
    '        '.split(''),
    '        '.split(''),
    'PPPPPPPP'.split(''),
    'RNBQKBNR'.split('')
  ]
}

function parseFen(fen) {
  const parts = String(fen || START_FEN).split(/\s+/)
  const rows = (parts[0] || '8/8/8/8/8/8/8/8').split('/')
  const board = []
  for (let r = 0; r < 8; r++) {
    const row = []
    const text = rows[r] || '8'
    for (let i = 0; i < text.length; i++) {
      const ch = text.charAt(i)
      const empty = parseInt(ch, 10)
      if (empty > 0) {
        for (let n = 0; n < empty; n++) row.push('')
      } else {
        row.push(ch)
      }
    }
    while (row.length < 8) row.push('')
    board.push(row.slice(0, 8))
  }
  return { board: board, turn: parts[1] === 'b' ? 'b' : 'w' }
}

function boardToFen(board, turn) {
  const rows = []
  for (let r = 0; r < 8; r++) {
    let row = ''
    let empty = 0
    for (let c = 0; c < 8; c++) {
      const piece = board[r][c]
      if (!piece || piece === ' ') {
        empty++
      } else {
        if (empty) row += String(empty)
        empty = 0
        row += piece
      }
    }
    if (empty) row += String(empty)
    rows.push(row)
  }
  return rows.join('/') + ' ' + turn
}

function tokenizePgn(pgn) {
  let text = String(pgn || '')
  text = text.replace(/\[[^\]]*\]/g, ' ')
  text = text.replace(/\{[^}]*\}/g, ' ')
  while (/\([^()]*\)/.test(text)) text = text.replace(/\([^()]*\)/g, ' ')
  text = text.replace(/;[^\n]*/g, ' ')
  text = text.replace(/\$\d+/g, ' ')
  return text.split(/\s+/).filter(function (token) {
    if (!token) return false
    if (/^(1-0|0-1|1\/2-1\/2|\*)$/.test(token)) return false
    if (/^\d+\.(\.\.)?$/.test(token)) return false
    if (/^\d+\.\.\./.test(token)) return token.length > token.indexOf('...') + 3
    if (/^\d+\./.test(token)) return token.length > token.indexOf('.') + 1
    return true
  }).map(function (token) {
    return token.replace(/^\d+\.\.\./, '').replace(/^\d+\./, '')
  }).filter(Boolean)
}

function pathClear(board, fr, fc, tr, tc) {
  const dr = Math.sign(tr - fr)
  const dc = Math.sign(tc - fc)
  let r = fr + dr
  let c = fc + dc
  while (r !== tr || c !== tc) {
    if (board[r][c] && board[r][c] !== ' ') return false
    r += dr
    c += dc
  }
  return true
}

function canMove(board, piece, fr, fc, tr, tc, capture) {
  const white = piece === piece.toUpperCase()
  const kind = piece.toLowerCase()
  const dr = tr - fr
  const dc = tc - fc
  const target = board[tr][tc]
  if (target && target !== ' ' && (target === target.toUpperCase()) === white) return false

  if (kind === 'p') {
    const dir = white ? -1 : 1
    const start = white ? 6 : 1
    if (capture) return dr === dir && Math.abs(dc) === 1
    if (dc !== 0) return false
    if (dr === dir && (!target || target === ' ')) return true
    if (fr === start && dr === dir * 2 && (!target || target === ' ') && (!board[fr + dir][fc] || board[fr + dir][fc] === ' ')) return true
    return false
  }
  if (kind === 'n') return (Math.abs(dr) === 2 && Math.abs(dc) === 1) || (Math.abs(dr) === 1 && Math.abs(dc) === 2)
  if (kind === 'b') return Math.abs(dr) === Math.abs(dc) && pathClear(board, fr, fc, tr, tc)
  if (kind === 'r') return (dr === 0 || dc === 0) && pathClear(board, fr, fc, tr, tc)
  if (kind === 'q') return ((Math.abs(dr) === Math.abs(dc)) || dr === 0 || dc === 0) && pathClear(board, fr, fc, tr, tc)
  if (kind === 'k') return Math.max(Math.abs(dr), Math.abs(dc)) === 1
  return false
}

function applySan(board, turn, rawSan) {
  let san = String(rawSan || '').trim()
  san = san.replace(/[!?]+/g, '').replace(/[+#]+$/g, '')
  if (!san || san === '--') return { board: board, turn: turn, ok: false }

  const white = turn === 'w'
  const home = white ? 7 : 0
  if (san === 'O-O' || san === '0-0') {
    board[home][6] = board[home][4]
    board[home][4] = ' '
    board[home][5] = board[home][7]
    board[home][7] = ' '
    return { board: board, turn: white ? 'b' : 'w', ok: true }
  }
  if (san === 'O-O-O' || san === '0-0-0') {
    board[home][2] = board[home][4]
    board[home][4] = ' '
    board[home][3] = board[home][0]
    board[home][0] = ' '
    return { board: board, turn: white ? 'b' : 'w', ok: true }
  }

  const targetMatch = san.match(/([a-h][1-8])(?:=([QRBN]))?$/)
  if (!targetMatch) return { board: board, turn: turn, ok: false }

  const targetSquare = targetMatch[1]
  const promotion = targetMatch[2] || ''
  const targetIndex = san.indexOf(targetSquare)
  let prefix = san.substring(0, targetIndex)
  const capture = prefix.indexOf('x') >= 0
  prefix = prefix.replace(/x/g, '')

  let pieceKind = 'p'
  if (/^[KQRBN]/.test(prefix)) {
    pieceKind = prefix.charAt(0).toLowerCase()
    prefix = prefix.substring(1)
  }

  const tc = FILES.indexOf(targetSquare.charAt(0))
  const tr = 8 - parseInt(targetSquare.charAt(1), 10)
  const desired = white ? pieceKind.toUpperCase() : pieceKind
  const candidates = []
  for (let r = 0; r < 8; r++) {
    for (let c = 0; c < 8; c++) {
      if (board[r][c] !== desired) continue
      if (prefix.length === 2 && (FILES.charAt(c) + (8 - r)) !== prefix) continue
      if (prefix.length === 1 && /[a-h]/.test(prefix) && FILES.charAt(c) !== prefix) continue
      if (prefix.length === 1 && /[1-8]/.test(prefix) && String(8 - r) !== prefix) continue
      if (canMove(board, desired, r, c, tr, tc, capture)) candidates.push({ r: r, c: c })
    }
  }
  if (!candidates.length) return { board: board, turn: turn, ok: false }

  const from = candidates[0]
  if (pieceKind === 'p' && capture && (!board[tr][tc] || board[tr][tc] === ' ')) {
    const dir = white ? -1 : 1
    board[tr - dir][tc] = ' '
  }
  board[tr][tc] = promotion ? (white ? promotion : promotion.toLowerCase()) : board[from.r][from.c]
  board[from.r][from.c] = ' '
  return { board: board, turn: white ? 'b' : 'w', ok: true }
}

// The position to solve, replayed from the game. Lichess's `initialPly` is the
// 0-based index of the last move played before the solver's turn, so the
// position comes after initialPly + 1 plies. Without one, the whole PGN is
// replayed: Lichess ends the game's PGN at the puzzle.
function fenFromPgn(pgn, initialPly) {
  let board = initialBoard()
  let turn = 'w'
  const moves = tokenizePgn(pgn)
  const lastPlyIndex = parseInt(initialPly, 10)
  const targetPly = isNaN(lastPlyIndex) ? moves.length : Math.max(0, lastPlyIndex + 1)
  let ply = 0
  for (let i = 0; i < moves.length && ply < targetPly; i++) {
    const result = applySan(board, turn, moves[i])
    if (!result.ok) continue
    board = result.board
    turn = result.turn
    ply++
  }
  if (ply === 0 && targetPly > 0) return ''
  return boardToFen(board, turn)
}

// The board and the card read the position from `game.fen`. Lichess sends the
// position to solve, side to move included, as `puzzle.fen`: that wins. Without
// it a `game.fen` is used as it is, else the position is replayed from the PGN.
function normalizePuzzle(data) {
  const puzzle = data && data.puzzle ? data : null
  if (!puzzle || !puzzle.game) return null
  const puzzleFen = puzzle.puzzle && puzzle.puzzle.fen ? String(puzzle.puzzle.fen) : ''
  if (!puzzleFen && puzzle.game.fen) return puzzle

  const fen = puzzleFen || fenFromPgn(puzzle.game.pgn, puzzle.puzzle && puzzle.puzzle.initialPly)
  if (!fen) return null
  const copy = JSON.parse(JSON.stringify(puzzle))
  copy.game.fen = fen
  return copy
}

function squareToPoint(square, boardX, boardY, squareSize, flipped) {
  const file = FILES.indexOf(square.charAt(0))
  const rank = parseInt(square.charAt(1), 10)
  if (file < 0 || rank < 1 || rank > 8) return null
  const col = flipped ? 7 - file : file
  const row = flipped ? rank - 1 : 8 - rank
  return { x: boardX + (col + 0.5) * squareSize, y: boardY + (row + 0.5) * squareSize }
}

function wrapText(text, maxChars, maxLines) {
  const words = String(text || '').split(/\s+/).filter(Boolean)
  const lines = []
  let line = ''
  for (let i = 0; i < words.length; i++) {
    const word = words[i]
    const next = line ? line + ' ' + word : word
    if (next.length <= maxChars || !line) {
      line = next
    } else {
      lines.push(line)
      line = word
      if (lines.length >= maxLines) break
    }
  }
  if (line && lines.length < maxLines) lines.push(line)
  if (words.length && lines.length === maxLines) {
    const used = lines.join(' ').split(/\s+/).filter(Boolean).length
    if (used < words.length) lines[maxLines - 1] = lines[maxLines - 1].replace(/[.,;:]*$/, '') + '…'
  }
  return lines
}

// Coordinates and sizes worked out in code go into the drawing with two decimals.
function px(value) {
  return value.toFixed(2)
}

// One <text> per line, `lineHeight` apart, the first line's baseline at y.
function TextLines({ lines, x, y, size, color, anchor = 'start', lineHeight, weight }) {
  const family = weight === 'bold' ? 'PTSans-Bold.ttf' : 'PTSans-Regular.ttf'
  return lines.map(function (line, i) {
    return (
      <text x={px(x)} y={px(y + i * lineHeight)} fontFamily={family} fontSize={px(size)} fill={color} textAnchor={anchor}>
        {line}
      </text>
    )
  })
}

// The faint pawn watermark in the corner of the info card.
function PawnIcon({ x, y, size, color, opacity }) {
  const s = size
  // A point `dx`, `dy` icon sizes away from the icon's centre, as path data.
  const at = (dx, dy) => px(x + s * dx) + ' ' + px(y + s * dy)
  return (
    <g opacity={opacity}>
      <circle cx={px(x)} cy={px(y - s * 0.26)} r={px(s * 0.16)} fill={color} />
      <path d={`M ${at(-0.21, -0.04)} C ${at(-0.18, -0.24)} ${at(0.18, -0.24)} ${at(0.21, -0.04)} L ${at(0.12, 0.22)} L ${at(-0.12, 0.22)} Z`} fill={color} />
      <rect x={px(x - s * 0.28)} y={px(y + s * 0.22)} width={px(s * 0.56)} height={px(s * 0.1)} rx={px(s * 0.04)} fill={color} />
      <rect x={px(x - s * 0.38)} y={px(y + s * 0.34)} width={px(s * 0.76)} height={px(s * 0.1)} rx={px(s * 0.05)} fill={color} />
    </g>
  )
}

// Bold Staunton-inspired silhouettes: the crown, cross, mitre and horse head
// are intentionally much larger than their bases for instant recognition.
// Drawn on a 100-unit square around 0,0; Piece scales them to the square.
function Silhouette({ kind, stroke }) {
  if (kind === 'k') {
    return (
      <>
        <path d="M-4-37H4v7h7v7H4v8H-4v-8h-7v-7h7z" />
        <path d="M-12-12H12L16 22H21v7H-21v-7h5z" />
        <rect x="-23" y="30" width="46" height="7" rx="2" />
      </>
    )
  }
  if (kind === 'q') {
    return (
      <>
        <path d="M-21-28L-10-10 0-34 10-10 21-28 15 23H22v7H-22v-7h7z" />
        <circle cx="-21" cy="-28" r="4" />
        <circle cx="0" cy="-34" r="4" />
        <circle cx="21" cy="-28" r="4" />
        <rect x="-24" y="30" width="48" height="7" rx="2" />
      </>
    )
  }
  if (kind === 'b') {
    return (
      <>
        <path d="M0-38C-22-20-19 2-9 20H9C19 2 22-20 0-38z" />
        <path d="M-11-20L11-2" fill="none" stroke={stroke} strokeWidth="4" />
        <rect x="-20" y="21" width="40" height="9" rx="2" />
        <rect x="-25" y="30" width="50" height="7" rx="2" />
      </>
    )
  }
  // The knight.
  return (
    <>
      <path d="M-20 23H19L13 4C21-22 6-38-12-29l4 12-10 16z" />
      <path d="M-7-28L-20-38-16-13" />
      <circle cx="7" cy="-17" r="3" fill={stroke} stroke="none" />
      <rect x="-24" y="23" width="48" height="8" rx="2" />
    </>
  )
}

function Piece({ piece, cx, cy, sq }) {
  const white = piece === piece.toUpperCase()
  const fill = white ? '#fffaf0' : '#14212a'
  const stroke = white ? '#26323a' : '#f7ead7'
  const kind = piece.toLowerCase()
  const u = sq * 0.1
  // A point `dx`, `dy` tenths of a square away from the square's centre, as path data.
  const at = (dx, dy) => px(cx + u * dx) + ' ' + px(cy + u * dy)

  // Every piece's outline is this many pixels wide.
  const outline = Math.max(0.8, sq * 0.016)

  let shapes
  if (kind === 'k' || kind === 'q' || kind === 'b' || kind === 'n') {
    // The scale applies to stroke widths too, so the silhouettes get the
    // outline divided by it.
    const scale = sq * 0.01
    shapes = (
      <g transform={`translate(${px(cx)} ${px(cy)}) scale(${scale.toFixed(3)})`} strokeWidth={(outline / scale).toFixed(3)}>
        <Silhouette kind={kind} stroke={stroke} />
      </g>
    )
  } else {
    // The pawn, the rook, and a plain figure for a letter the FEN should not
    // hold, each standing on the same base.
    let figure
    if (kind === 'p') {
      figure = (
        <>
          <circle cx={px(cx)} cy={px(cy - u * 2.15)} r={px(u * 0.88)} />
          <path d={`M ${at(-1.35, 2.5)} L ${at(1.35, 2.5)} L ${at(0.85, -1.05)} Q ${at(0, -1.55)} ${at(-0.85, -1.05)} Z`} />
        </>
      )
    } else if (kind === 'r') {
      figure = (
        <>
          <path d={`M ${at(-1.25, 2.45)} L ${at(1.25, 2.45)} L ${at(0.86, -1.5)} L ${at(-0.86, -1.5)} Z`} />
          <path d={`M ${at(-1.15, -1.5)} L ${at(-1.15, -2.35)} L ${at(-0.52, -2.35)} L ${at(-0.52, -1.88)} L ${at(0.52, -1.88)} L ${at(0.52, -2.35)} L ${at(1.15, -2.35)} L ${at(1.15, -1.5)} Z`} />
        </>
      )
    } else {
      figure = (
        <>
          <path d={`M ${at(-1.3, 2.45)} L ${at(1.3, 2.45)} L ${at(0.92, -0.45)} L ${at(0, -2.85)} L ${at(-0.92, -0.45)} Z`} />
          <path d={`M ${at(-0.48, -1.65)} L ${at(0.5, -0.6)}`} fill="none" stroke={stroke} strokeWidth={px(Math.max(1.5, sq * 0.03))} />
        </>
      )
    }
    shapes = (
      <>
        {figure}
        <rect x={px(cx - u * 1.65)} y={px(cy + u * 2.42)} width={px(u * 3.3)} height={px(u * 0.42)} rx={px(u * 0.14)} />
      </>
    )
  }

  return (
    <g fill={fill} stroke={stroke} strokeWidth={px(outline)} strokeLinejoin="round">
      {shapes}
    </g>
  )
}

function Board({ params, puzzle, revealed }) {
  const fen = parseFen(puzzle.game && puzzle.game.fen)
  const flipped = params.autoOrient && fen.turn === 'b'
  const boardX = params.boardX
  const boardY = params.boardY
  const boardSize = params.boardSize
  const sq = boardSize / 8
  const firstMove = puzzle.puzzle && puzzle.puzzle.solution ? puzzle.puzzle.solution[0] : ''
  const from = firstMove ? firstMove.substring(0, 2) : ''
  const to = firstMove ? firstMove.substring(2, 4) : ''
  const fromPoint = revealed ? squareToPoint(from, boardX, boardY, sq, flipped) : null
  const toPoint = revealed ? squareToPoint(to, boardX, boardY, sq, flipped) : null

  // The squares, with the first move's two squares marked once revealed.
  const squares = []
  for (let row = 0; row < 8; row++) {
    for (let col = 0; col < 8; col++) {
      const file = flipped ? 7 - col : col
      const rankIndex = flipped ? 7 - row : row
      const squareName = FILES.charAt(file) + (8 - rankIndex)
      const fill = (row + col) % 2 === 0 ? params.lightSquare : params.darkSquare
      const x = boardX + col * sq
      const y = boardY + row * sq
      squares.push(<rect x={px(x)} y={px(y)} width={px(sq)} height={px(sq)} fill={fill} />)
      if (revealed && (squareName === from || squareName === to)) {
        squares.push(<rect x={px(x + sq * 0.06)} y={px(y + sq * 0.06)} width={px(sq * 0.88)} height={px(sq * 0.88)} fill={params.accent} opacity="0.18" />)
        squares.push(<rect x={px(x + sq * 0.08)} y={px(y + sq * 0.08)} width={px(sq * 0.84)} height={px(sq * 0.84)} fill="none" stroke={params.accent} strokeWidth={px(Math.max(2, sq * 0.045))} />)
      }
    }
  }

  const coordinates = []
  if (params.showCoordinates) {
    const coordSize = clamp(sq * 0.17, 7, 18)
    for (let i = 0; i < 8; i++) {
      const fileLabel = flipped ? FILES.charAt(7 - i) : FILES.charAt(i)
      const rankLabel = flipped ? String(i + 1) : String(8 - i)
      coordinates.push(
        <text x={px(boardX + i * sq + sq * 0.08)} y={px(boardY + boardSize - sq * 0.08)} fontFamily="PTSans-Bold.ttf" fontSize={px(coordSize)} fill="#19232a" opacity="0.62">
          {fileLabel}
        </text>
      )
      coordinates.push(
        <text x={px(boardX + sq * 0.08)} y={px(boardY + i * sq + coordSize + sq * 0.06)} fontFamily="PTSans-Bold.ttf" fontSize={px(coordSize)} fill="#19232a" opacity="0.62">
          {rankLabel}
        </text>
      )
    }
  }

  const pieces = []
  for (let row = 0; row < 8; row++) {
    for (let col = 0; col < 8; col++) {
      const piece = fen.board[row][col]
      if (!piece) continue
      const boardCol = flipped ? 7 - col : col
      const boardRow = flipped ? 7 - row : row
      const cx = boardX + (boardCol + 0.5) * sq
      const cy = boardY + (boardRow + 0.5) * sq
      pieces.push(<Piece piece={piece} cx={cx} cy={cy} sq={sq} />)
    }
  }

  // Once revealed, an arrow (with a soft shadow) along the first move.
  let arrow = null
  if (fromPoint && toPoint) {
    const angle = Math.atan2(toPoint.y - fromPoint.y, toPoint.x - fromPoint.x)
    const head = sq * 0.18
    const endX = toPoint.x - Math.cos(angle) * sq * 0.26
    const endY = toPoint.y - Math.sin(angle) * sq * 0.26
    const startX = fromPoint.x + Math.cos(angle) * sq * 0.26
    const startY = fromPoint.y + Math.sin(angle) * sq * 0.26
    const leftX = endX - Math.cos(angle) * head - Math.cos(angle + Math.PI / 2) * head * 0.72
    const leftY = endY - Math.sin(angle) * head - Math.sin(angle + Math.PI / 2) * head * 0.72
    const rightX = endX - Math.cos(angle) * head - Math.cos(angle - Math.PI / 2) * head * 0.72
    const rightY = endY - Math.sin(angle) * head - Math.sin(angle - Math.PI / 2) * head * 0.72
    arrow = (
      <>
        <line x1={px(startX + sq * 0.02)} y1={px(startY + sq * 0.02)} x2={px(endX + sq * 0.02)} y2={px(endY + sq * 0.02)} stroke="#08131b" strokeWidth={px(Math.max(3, sq * 0.1))} opacity="0.22" />
        <line x1={px(startX)} y1={px(startY)} x2={px(endX)} y2={px(endY)} stroke={params.accent} strokeWidth={px(Math.max(3, sq * 0.085))} />
        <polygon points={`${px(endX)},${px(endY)} ${px(leftX)},${px(leftY)} ${px(rightX)},${px(rightY)}`} fill={params.accent} />
      </>
    )
  }

  return (
    <>
      {/* Shadow, frame and inner rim around the board */}
      <rect x={px(boardX - boardSize * 0.045)} y={px(boardY + boardSize * 0.035)} width={px(boardSize * 1.09)} height={px(boardSize * 1.03)} rx={px(sq * 0.28)} fill="#05101a" opacity="0.28" />
      <rect x={px(boardX - boardSize * 0.032)} y={px(boardY - boardSize * 0.032)} width={px(boardSize * 1.064)} height={px(boardSize * 1.064)} rx={px(sq * 0.22)} fill="#0b1621" />
      <rect x={px(boardX - boardSize * 0.018)} y={px(boardY - boardSize * 0.018)} width={px(boardSize * 1.036)} height={px(boardSize * 1.036)} rx={px(sq * 0.16)} fill="#d8c6a6" opacity="0.28" />
      {squares}
      <rect x={px(boardX)} y={px(boardY)} width={px(boardSize)} height={px(boardSize)} fill="none" stroke="#13202a" strokeWidth={px(Math.max(1.5, sq * 0.026))} />
      {coordinates}
      {pieces}
      {arrow}
    </>
  )
}

function InfoCard({ params, puzzle, revealed }) {
  const x = params.infoX
  const y = params.infoY
  const w = params.infoW
  const h = params.infoH
  const pad = params.infoPad
  const puzzleData = puzzle.puzzle || {}
  const fen = parseFen(puzzle.game && puzzle.game.fen)
  const side = fen.turn === 'b' ? 'Black' : 'White'
  const titleSize = clamp(Math.min(w, h) * 0.105, 22, 48)
  const small = clamp(Math.min(w, h) * 0.052, 12, 22)
  const body = clamp(Math.min(w, h) * 0.064, 15, 28)
  let cursor = y + pad

  // The card's text, top to bottom: `cursor` is where the next block starts.
  const content = []

  const titleLines = wrapText(params.title, Math.max(8, Math.floor((w - pad * 2) / (titleSize * 0.52))), 2)
  content.push(<TextLines lines={titleLines} x={x + pad} y={cursor + titleSize} size={titleSize} color="#14202b" lineHeight={titleSize * 1.05} weight="bold" />)
  cursor += titleLines.length * titleSize * 1.05 + small * 0.6

  const meta = []
  if (puzzleData.rating) meta.push('Rated ' + puzzleData.rating)
  if (puzzleData.id) meta.push('#' + puzzleData.id)
  if (puzzle.notice) meta.push('Sample')
  if (meta.length) {
    // Wrapped like the rest of the card's text (digits and short words: half
    // the font size a character), and no line starts or ends with a separator.
    const metaLines = wrapText(meta.join(' · '), Math.max(10, Math.floor((w - pad * 2) / (small * 0.5))), 2).map(function (line) {
      return line.replace(/^·\s*/, '').replace(/\s*·(…?)$/, '$1')
    })
    content.push(<TextLines lines={metaLines} x={x + pad} y={cursor + small} size={small} color="#5c665f" lineHeight={small * 1.2} weight="regular" />)
    cursor += (metaLines.length - 1) * small * 1.2 + small * 1.7
  }

  content.push(<line x1={px(x + pad)} y1={px(cursor)} x2={px(x + w - pad)} y2={px(cursor)} stroke="#d8cdb9" strokeWidth="1.4" />)
  cursor += pad * 0.9

  if (revealed) {
    const solution = (puzzleData.solution || []).map(moveToText).filter(Boolean)
    const headline = solution.length ? 'Solution: ' + solution[0] : 'Solution revealed'
    content.push(<TextLines lines={[headline]} x={x + pad} y={cursor + body} size={body} color={params.accent} lineHeight={body * 1.2} weight="bold" />)
    cursor += body * 1.65
    if (solution.length > 1) {
      const lines = wrapText(solution.join('  '), Math.max(10, Math.floor((w - pad * 2) / (small * 0.55))), 3)
      content.push(<TextLines lines={lines} x={x + pad} y={cursor + small} size={small} color="#26323a" lineHeight={small * 1.28} weight="regular" />)
      cursor += lines.length * small * 1.28 + small * 0.6
    }
    const noteLines = wrapText('The arrow marks the first move. Calculate the full line, then compare it with the continuation.', Math.max(12, Math.floor((w - pad * 2) / (small * 0.54))), 4)
    content.push(<TextLines lines={noteLines} x={x + pad} y={cursor + small} size={small} color="#5c665f" lineHeight={small * 1.28} weight="regular" />)
  } else {
    const promptLines = wrapText(side + ' to move. Find the strongest continuation.', Math.max(10, Math.floor((w - pad * 2) / (body * 0.54))), 3)
    content.push(<TextLines lines={promptLines} x={x + pad} y={cursor + body} size={body} color="#14202b" lineHeight={body * 1.22} weight="bold" />)
    cursor += promptLines.length * body * 1.22 + small
    const hintLines = wrapText('Press a frame button to reveal or hide the solution.', Math.max(12, Math.floor((w - pad * 2) / (small * 0.54))), 4)
    content.push(<TextLines lines={hintLines} x={x + pad} y={cursor + small} size={small} color="#5c665f" lineHeight={small * 1.28} weight="regular" />)
  }

  // The themes sit at the bottom of the card.
  if (params.showThemes && puzzleData.themes && puzzleData.themes.length) {
    const themes = puzzleData.themes.slice(0, 4).map(titleCaseTheme).join(' · ')
    const themeSize = clamp(small * 0.85, 10, 18)
    const lines = wrapText(themes, Math.max(12, Math.floor((w - pad * 2) / (themeSize * 0.54))), 2)
    const startY = y + h - pad - (lines.length - 1) * themeSize * 1.2
    content.push(<TextLines lines={lines} x={x + pad} y={startY} size={themeSize} color="#7b6b54" lineHeight={themeSize * 1.2} weight="regular" />)
  }

  return (
    <>
      {/* Shadow, paper, accent bar, a dot and the pawn watermark */}
      <rect x={px(x + pad * 0.18)} y={px(y + pad * 0.26)} width={px(w)} height={px(h)} rx={px(pad * 0.68)} fill="#05101a" opacity="0.22" />
      <rect x={px(x)} y={px(y)} width={px(w)} height={px(h)} rx={px(pad * 0.65)} fill="url(#paper)" />
      <rect x={px(x)} y={px(y)} width={px(Math.max(4, pad * 0.28))} height={px(h)} rx={px(pad * 0.18)} fill={params.accent} />
      <circle cx={px(x + w - pad * 0.9)} cy={px(y + pad * 1.05)} r={px(pad * 0.32)} fill={params.accent} opacity="0.16" />
      <PawnIcon x={x + w - pad * 1.4} y={y + h - pad * 1.35} size={Math.min(w, h) * 0.55} color={params.accent} opacity={0.08} />
      {content}
    </>
  )
}

function renderPuzzle(W, H, config, puzzle, revealed) {
  const m = Math.min(W, H)
  const pad = clamp(m * 0.045, 16, 54)
  const gap = clamp(m * 0.035, 14, 42)
  const portrait = H > W
  const params = {
    title: String(config.title || 'Chess puzzle of the day'),
    accent: hex(config.accentColor, '#c08457'),
    lightSquare: hex(config.lightSquare, '#f3ead7'),
    darkSquare: hex(config.darkSquare, '#6e7f71'),
    showCoordinates: boolValue(config.showCoordinates, true),
    autoOrient: boolValue(config.autoOrient, true),
    showThemes: boolValue(config.showThemes, true)
  }

  if (portrait) {
    // Give the board most of the screen width and height; the information card
    // uses the remaining full-width band below it.
    params.boardSize = Math.min(W - pad * 2, H * 0.7 - pad - gap)
    params.boardX = (W - params.boardSize) / 2
    params.boardY = pad
    params.infoX = pad
    params.infoY = params.boardY + params.boardSize + gap
    params.infoW = W - pad * 2
    params.infoH = H - params.infoY - pad
  } else {
    // Reserve only a readable minimum for the side card, so the board can
    // grow to nearly the full display height on wide panels.
    const minInfoWidth = Math.max(m * 0.32, W * 0.21)
    params.boardSize = Math.min(H - pad * 2, W - pad * 2 - gap - minInfoWidth)
    params.boardX = pad
    params.boardY = (H - params.boardSize) / 2
    params.infoX = params.boardX + params.boardSize + gap
    params.infoY = pad
    params.infoW = W - params.infoX - pad
    params.infoH = H - pad * 2
  }
  params.infoPad = clamp(Math.min(params.infoW, params.infoH) * 0.075, 14, 34)

  const bgTop = hex(config.backgroundTop, '#11243a')
  const bgBottom = hex(config.backgroundBottom, '#213b45')
  const boardCx = params.boardX + params.boardSize * 0.5
  const boardCy = params.boardY + params.boardSize * 0.5
  const glowR = params.boardSize * 0.8

  return (
    <svg xmlns="http://www.w3.org/2000/svg" width={W} height={H} viewBox={`0 0 ${W} ${H}`}>
      <defs>
        <linearGradient id="bg" gradientUnits="userSpaceOnUse" x1="0" y1="0" x2="0" y2={H}>
          <stop offset="0" stopColor={bgTop} />
          <stop offset="1" stopColor={bgBottom} />
        </linearGradient>
        <linearGradient id="paper" gradientUnits="userSpaceOnUse" x1={px(params.infoX)} y1={px(params.infoY)} x2={px(params.infoX + params.infoW)} y2={px(params.infoY + params.infoH)}>
          <stop offset="0" stopColor="#fff7e8" />
          <stop offset="1" stopColor="#eadcc4" />
        </linearGradient>
        <radialGradient id="boardGlow" gradientUnits="userSpaceOnUse" cx={px(boardCx)} cy={px(boardCy)} r={px(glowR)}>
          <stop offset="0" stopColor={params.accent} stopOpacity="0.34" />
          <stop offset="0.55" stopColor={params.accent} stopOpacity="0.12" />
          <stop offset="1" stopColor={params.accent} stopOpacity="0" />
        </radialGradient>
        <radialGradient id="cornerGlow" gradientUnits="userSpaceOnUse" cx={W} cy="0" r={px(m * 0.52)}>
          <stop offset="0" stopColor="#f4dca7" stopOpacity="0.24" />
          <stop offset="1" stopColor="#f4dca7" stopOpacity="0" />
        </radialGradient>
        <radialGradient id="vignette" gradientUnits="userSpaceOnUse" cx={px(W * 0.5)} cy={px(H * 0.5)} r={px(Math.max(W, H) * 0.74)}>
          <stop offset="0.58" stopColor="#07111b" stopOpacity="0" />
          <stop offset="1" stopColor="#07111b" stopOpacity="0.38" />
        </radialGradient>
      </defs>
      <rect x="0" y="0" width={W} height={H} fill="url(#bg)" />
      <rect x="0" y="0" width={W} height={H} fill="url(#cornerGlow)" />
      <circle cx={px(boardCx)} cy={px(boardCy)} r={px(glowR)} fill="url(#boardGlow)" />
      <circle cx={px(W - pad * 1.2)} cy={px(pad * 1.15)} r={px(m * 0.18)} fill={params.accent} opacity="0.12" />
      <circle cx={px(pad * 0.8)} cy={px(H - pad * 0.6)} r={px(m * 0.22)} fill="#ffffff" opacity="0.035" />
      <Board params={params} puzzle={puzzle} revealed={revealed} />
      <InfoCard params={params} puzzle={puzzle} revealed={revealed} />
      <rect x="0" y="0" width={W} height={H} fill="url(#vignette)" />
    </svg>
  )
}

export function get(app, context) {
  const W = context.imageWidth || app.frame.width
  const H = context.imageHeight || app.frame.height
  const url = String(app.config.puzzleUrl || '').trim() || 'https://lichess.org/api/puzzle/daily'
  let puzzle = null

  try {
    puzzle = normalizePuzzle(frameos.fetchJson(url))
  } catch (error) {
    puzzle = null
  }

  if (!puzzle) {
    puzzle = SAMPLE_PUZZLE
  }

  const puzzleId = String((puzzle.puzzle && puzzle.puzzle.id) || (puzzle.game && puzzle.game.id) || (puzzle.game && puzzle.game.fen) || 'daily')
  const saved = app.state.lichessPuzzleOfTheDay || {}
  const revealed = saved.puzzleId === puzzleId && saved.revealed === true

  frameos.setState('lichessPuzzleOfTheDay', {
    puzzleId: puzzleId,
    seen: true,
    revealed: revealed,
    lastEvent: context.event || 'render'
  })

  return renderPuzzle(W, H, app.config, puzzle, revealed)
}

