export function run(app, context) {
  const saved = app.state.lichessPuzzleOfTheDay || {}
  frameos.setState('lichessPuzzleOfTheDay', {
    puzzleId: saved.puzzleId || '',
    seen: true,
    revealed: !saved.revealed,
    lastEvent: context.event || 'button'
  })
  return null
}
